create table TB_VOUCHER_INFO (VOUCHER_ID INT not null  ,BRANCH VARCHAR(30) null  ,TAILBOX_ID VARCHAR(30) null  ,DOC_TYPE VARCHAR(4) null  ,PREFIX VARCHAR(10) null  ,VOUCHER_START_NO VARCHAR(60) null  ,VOUCHER_END_NO VARCHAR(60) null  ,START_NO_INT INT null  ,END_NO_INT INT null  ,VOUCHER_SUM INT null  ,VOUCHER_STATUS VARCHAR(3) null  ,EOPD_VOUCHER_SUM INT null  ,SOPD_VOUCHER_SUM INT null  ,CCY VARCHAR(3) null  ,TRAN_AMT DECIMAL(17,2) null  ,REMARK VARCHAR(200) null  ,LAST_USER_ID VARCHAR(30) null  ,UPDATE_DATE TIMESTAMP(3) null  ,TRAN_TIMESTAMP VARCHAR(26) null  ,COMPANY VARCHAR(20) null  ,CREATE_TIMESTAMP VARCHAR(26) null  ,LAST_CHANGE_DATE TIMESTAMP(3) null  , primary key(VOUCHER_ID));